// Pick sheet rows that Katie has moved past blank (READY or later) and that have an evidence folder (v1.7 rows).
const rows = $('Read queue').all().map(i => i.json).filter(r => r && r.post_id);
const ok = /^(READY|STAGED|PUBLISHED|POSTED)$/i;
const out = [];
for (const r of rows) {
  if (!ok.test(String(r.status || '').trim())) continue;
  const m = String(r.notes || '').match(/drive\.google\.com\/drive\/folders\/([A-Za-z0-9_-]+)/);
  if (!m) continue;
  out.push({ json: { post_id: r.post_id, title: r.title || '', headline: r.headline || '', subline: r.subline || '', caption: r.caption || '', fact_status: r.fact_status || '', folder_id: m[1] } });
}
return out;

// Keep only rows whose folder has a dossier and no script yet. Max per run from Config.
const rows = $('Pick rows').all().map(i => i.json);
const out = [];
$input.all().forEach((it, i) => {
  const r = rows[i]; const files = (it.json && it.json.files) || [];
  const d = files.find(f => /dossier/i.test(f.name || ''));
  const has = files.some(f => /10-min script/i.test(f.name || ''));
  if (!d || has) return;
  out.push({ json: { ...r, dossier_id: d.id, dossier_mime: d.mimeType || '' } });
});
const max = +$('Config').first().json.max_per_run || 3;
return out.slice(0, max);

// One chat-completions call per row: the 10-minute on-camera script.
const cfg = $('Config').first().json;
const prompt = $('Fetch script prompt').first().json.prompt_md || '';
const voice = $('Fetch Bart voice').first().json.voice_md || '';
const persp = $('Fetch Bart perspectives').first().json.perspectives_md || '';
const r = $('Needs script').item.json;
const dossier = String($json.dossier_text || '').slice(0, 60000);
const sys = `You are Peggy, writing a 10-minute on-camera script for Bart Baggett inside an automated n8n run.

AUTOMATED-RUN OVERRIDES (these win over the files where they differ):
1. Follow QDE_FamousCase_Video_Script_Prompt_10min_v1 below exactly: structure, word count (1,300 to 1,500 spoken words), the three [AD BREAK] markers, the output format, and the TO VERIFY list.
2. Use ONLY facts in the DOSSIER and FACT CARD supplied. Never add a fact from memory. If the dossier is thin, write a shorter honest script and say so in TO VERIFY.
3. Bart's perspective appears in the dossier under "Bart perspective" and in BART_FORENSIC_PERSPECTIVES.md. Apply rule 5 of the prompt. The case note in BART_FORENSIC_PERSPECTIVES.md wins on any conflict. A look at a published copy is never an official opinion.
4. Return ONLY the finished script in the output format (Markdown). No preamble.

===== QDE_FamousCase_Video_Script_Prompt_10min_v1.md =====
${prompt}

===== BART_BAGGETT_VOICE.MD =====
${voice}

===== BART_FORENSIC_PERSPECTIVES.md =====
${persp}`;
const user = `POST ID: ${r.post_id}
HEADLINE: ${r.headline}
SUB-LINE: ${r.subline}
CASE: ${r.title}

FACT CARD (sheet column N):
${r.fact_status}

DOSSIER (evidence folder, dossier file):
${dossier}`;
const cm = cfg.model || 'gpt-5.5';
const body = { model: cm, messages: [{ role: 'system', content: sys }, { role: 'user', content: user }] };
if (/^(gpt-5|o\d)/.test(cm)) body.reasoning_effort = 'medium'; else body.temperature = 0.5;
return { json: { post_id: r.post_id, body } };

// Check the script against the prompt's acceptance test and build the file text.
const r = $('Needs script').item.json;
const j = $json;
const text = String((j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '').trim();
const flags = [];
if (!text) flags.push('NO SCRIPT RETURNED' + (j.error ? ': ' + String(j.error.message || '').slice(0, 150) : ''));
const m = text.match(/##\s*SCRIPT\s*\n([\s\S]*?)(?:\n##\s*EXHIBIT CUE SHEET|$)/i);
const body = m ? m[1] : text;
const spoken = body.replace(/\[[^\]]*\]/g, ' ');
const words = spoken.split(/\s+/).filter(Boolean).length;
if (text && (words < 1200 || words > 1650)) flags.push(`${words} WORDS (target 1,300 to 1,500)`);
for (const k of [1, 2, 3]) if (text && !text.includes(`[AD BREAK ${k}]`)) flags.push(`MISSING [AD BREAK ${k}]`);
if (text && !/1-800-980-9030/.test(text)) flags.push('PHONE CTA MISSING');
if (/handwritingexpert\.com/i.test(text)) flags.push('BANNED DOMAIN HandwritingExpert.com');
if (/grapholog/i.test(spoken)) flags.push('GRAPHOLOGY IN SPOKEN TEXT');
if (/\bI (authenticated|examined the original|testified|was hired|was retained)\b/i.test(spoken)) flags.push('CHECK: script says Bart examined/testified/was hired');
if (/official opinion/i.test(spoken) && !/not an official opinion/i.test(spoken)) flags.push('CHECK: "official opinion" wording');
const footer = `\n\n---\nGenerated ${$now.setZone('America/Chicago').toFormat('yyyy-LL-dd HH:mm')} by Peggy (${$('Config').first().json.model}) from the dossier. Spoken words: ${words}. Auto-check flags: ${flags.join('; ') || 'none'}.\n`;
return { json: { post_id: r.post_id, headline: r.headline, folder_id: r.folder_id, words, flags, has_text: !!text, file_name: `${r.post_id} 10-min script`, file_text: text + footer } };

// Slack note: which scripts were written, where, and what to check.
const checks = $('Check script').all().map(i => i.json).filter(c => c.has_text);
const lines = [];
lines.push(`${checks.length} new 10-minute on-camera script${checks.length === 1 ? '' : 's'} saved to the story evidence folder${checks.length === 1 ? '' : 's'} (Google Drive > QDE Evidence). Read each one before filming and clear its TO VERIFY list.`);
lines.push('');
for (const c of checks) {
  lines.push(`• ${c.post_id} — ${c.headline} · ${c.words} words · flags: ${c.flags.join('; ') || 'none'}`);
  lines.push(`    https://drive.google.com/drive/folders/${c.folder_id}`);
}
return [{ json: { text: lines.join('\n') } }];
